// DEFINE what counts as an incident HERE. Adapt these rules to your service.
// $json is the response from your status API.
const data = $json || {};
const problems = [];

// Rule 1: the status field must equal 'ok'.
if (data.status && data.status !== 'ok') {
  problems.push('The service reports status "' + data.status + '"');
}

// Rule 2: too many pending cases (change the 20 threshold to yours).
const pending = Number(data.pending || 0);
if (pending > 20) {
  problems.push('There are ' + pending + ' pending cases (threshold: 20)');
}

// Rule 3 (example, delete or adapt): empty response = suspicious.
if (Object.keys(data).length === 0) {
  problems.push('The status API returned an empty response');
}

return [ { json: {
  alert: problems.length > 0,
  reason: problems.join(' · ') || 'no incidents',
  checkedAt: new Date().toISOString()
} } ];

